import{_ as r,a as o,b as s,c as n,d as e,e as a,f as g}from"./chunks/project-settings.D6ONafTS.js";import{_ as i,o as d,c as l,a2 as h}from"./chunks/framework.Bzj1XTnB.js";const k=JSON.parse('{"title":"एडिटर","description":"ड्रॉइंग स्क्रीन को समझें — पट्टियाँ, टूलबार, जेस्चर, अनडू और ज़ूम।","frontmatter":{"lang":"hi","slug":"the-editor","order":2,"title":"एडिटर","description":"ड्रॉइंग स्क्रीन को समझें — पट्टियाँ, टूलबार, जेस्चर, अनडू और ज़ूम।"},"headers":[],"relativePath":"hi/the-editor.md","filePath":"hi/the-editor.md"}'),c={name:"hi/the-editor.md"};function p(m,t,u,b,_,f){return d(),l("div",null,[...t[0]||(t[0]=[h('<h1 id="एडिटर" tabindex="-1">एडिटर <a class="header-anchor" href="#एडिटर" aria-label="Permalink to &quot;एडिटर&quot;">​</a></h1><p>यहीं आप ड्रॉ करते हैं। हर हिस्सा क्या करता है, नीचे देखें।</p><p><img src="'+r+'" alt="एडिटर"></p><h2 id="ऊपर-की-पट्टी" tabindex="-1">ऊपर की पट्टी <a class="header-anchor" href="#ऊपर-की-पट्टी" aria-label="Permalink to &quot;ऊपर की पट्टी&quot;">​</a></h2><table tabindex="0"><thead><tr><th>बटन</th><th>क्या करता है</th></tr></thead><tbody><tr><td><strong>✕</strong></td><td>सेव करके प्रोजेक्ट बंद करता है</td></tr><tr><td><strong>गुलाबी हीरा</strong></td><td><strong>Object library</strong> खोलता है — तैयार कैरेक्टर या आपके सेव किए ऑब्जेक्ट जोड़ने के लिए</td></tr><tr><td><strong>TIMELINE</strong></td><td>पूरी टाइमलाइन खोलता है (<em>फ़्रेम और टाइमलाइन</em> देखें)</td></tr><tr><td><strong>Hide interface</strong> (चौकोर आइकन)</td><td>पट्टियाँ छिपाता है ताकि ड्रॉइंग ज़्यादा दिखे</td></tr><tr><td><strong>गुलाबी शेयर तीर</strong></td><td><strong>Make movie</strong> — अपना एनिमेशन एक्सपोर्ट करें</td></tr><tr><td><strong>⋮</strong></td><td>प्रोजेक्ट मेन्यू: तस्वीर, ऑडियो, स्टिकर, ओनियन स्किन, ग्रिड, प्रोजेक्ट सेटिंग और भी</td></tr></tbody></table><h2 id="टूलबार" tabindex="-1">टूलबार <a class="header-anchor" href="#टूलबार" aria-label="Permalink to &quot;टूलबार&quot;">​</a></h2><p>ऊपर की सफ़ेद पट्टी में आपके टूल हैं: <strong>Brush</strong>, <strong>Eraser</strong>, <strong>Lasso</strong>, <strong>Fill</strong>, एक और टूल जो आपके पिछली बार इस्तेमाल किए टूल में बदल जाता है (शुरू में Text), और बाकी के लिए <strong>⋯</strong> (<strong>Text</strong>, <strong>Smudge</strong>, <strong>Blur</strong>, <strong>Magic cut</strong>, <strong>Eyedropper</strong>)।</p><p><img src="'+o+'" alt="और टूल"></p><p>टूलबार को कहीं भी रख सकते हैं:</p><ul><li>बाएँ सिरे की <strong>बिंदुओं वाली पकड़ खींचें</strong> — टूलबार हिलता है।</li><li><strong>पकड़ पर टैप करें</strong> — टूलबार लेटा या खड़ा हो जाता है।</li><li><strong>स्क्रीन के किनारे पर छोड़ें</strong> — किनारे के साथ खड़ा हो जाता है।</li><li><strong>नीचे फ़्रेम के पास छोड़ें</strong> — सिमटकर सिर्फ़ मौजूदा टूल और एक तीर बचता है। किसी पर भी टैप करें तो सारे टूल एक कॉलम में दिखते हैं। खोलने के लिए वापस ऊपर खींचें।</li></ul><p><img src="'+s+'" alt="सिमटा टूलबार, टूल की सूची खुली हुई"></p><h2 id="टूल-विकल्प-वाली-पट्टी" tabindex="-1">टूल विकल्प वाली पट्टी <a class="header-anchor" href="#टूल-विकल्प-वाली-पट्टी" aria-label="Permalink to &quot;टूल विकल्प वाली पट्टी&quot;">​</a></h2><p>दाएँ किनारे की पट्टी टूल के हिसाब से बदलती है। ब्रश के लिए इसमें <strong>Brush</strong> (ब्रश चुनें), <strong>Size</strong>, <strong>Opacity</strong>, <strong>Color</strong> और <strong>Ruler</strong> हैं।</p><ul><li>किसी कंट्रोल पर <strong>ऊपर या नीचे खींचें</strong> — बदलता है, और एक बुलबुला उसकी वैल्यू दिखाता है।</li><li>किसी कंट्रोल पर <strong>टैप या लॉन्ग-प्रेस</strong> — उस टूल की सारी सेटिंग खुलती हैं।</li><li><strong>Color पर टैप</strong> — रंग चुनने वाला खुलता है।</li><li>ऊपर की पकड़ खींचकर पट्टी को कहीं भी ले जाएँ। किसी किनारे के पास छोड़ें तो वह उसी किनारे से लग जाती है। (Settings में <strong>Left-handed toolbar</strong> चालू करने पर यह बाएँ किनारे से शुरू होती है।)</li><li>नीचे टाइमलाइन के पास छोड़ें तो पट्टी सिमटकर सिर्फ़ मुख्य कंट्रोल (ब्रश के लिए <strong>Size</strong> और <strong>Color</strong>) और एक तीर दिखाती है। तीर पर टैप करें तो बाकी कंट्रोल ऊपर की ओर खुलते हैं, दोबारा टैप करें तो सिमट जाते हैं। ऊपर खींचें तो पूरी खुल जाती है।</li></ul><h2 id="नीचे-की-पट्टी" tabindex="-1">नीचे की पट्टी <a class="header-anchor" href="#नीचे-की-पट्टी" aria-label="Permalink to &quot;नीचे की पट्टी&quot;">​</a></h2><p><strong>Audio</strong>, <strong>Image/Video</strong>, <strong>Undo</strong>, <strong>Redo</strong>, <strong>Copy</strong>, <strong>Paste</strong> और <strong>Layer</strong> (गुलाबी नंबर वह लेयर है जिस पर आप ड्रॉ कर रहे हैं)। इसके ठीक ऊपर आपके एनिमेशन के फ़्रेम हैं।</p><ul><li><strong>Copy</strong> — जो चुना है वह कॉपी होता है; कुछ न चुना हो तो पूरी लेयर।</li><li><strong>Paste</strong> — उसे <strong>उसी जगह</strong> चुने हुए रूप में वापस रखता है — ड्रॉइंग अगले फ़्रेम पर ले जाने के लिए बढ़िया।</li></ul><h2 id="कैनवास-पर-जेस्चर" tabindex="-1">कैनवास पर जेस्चर <a class="header-anchor" href="#कैनवास-पर-जेस्चर" aria-label="Permalink to &quot;कैनवास पर जेस्चर&quot;">​</a></h2><table tabindex="0"><thead><tr><th>जेस्चर</th><th>क्या होता है</th></tr></thead><tbody><tr><td>एक उँगली</td><td>मौजूदा टूल से ड्रॉ</td></tr><tr><td>दो उँगलियों से पिंच</td><td>ज़ूम इन और आउट</td></tr><tr><td>दो उँगलियों से खींचना</td><td>कैनवास पर इधर-उधर जाना</td></tr><tr><td>दो उँगलियों से घुमाना</td><td>कैनवास घुमाना (Settings में बंद कर सकते हैं)</td></tr><tr><td>दो उँगलियों से टैप</td><td><strong>Undo</strong></td></tr><tr><td>तीन उँगलियों से टैप</td><td><strong>Redo</strong></td></tr><tr><td>चलते एनिमेशन पर कोई भी टैप</td><td>एनिमेशन रोकता है</td></tr></tbody></table><h2 id="smooth-zoom" tabindex="-1">Smooth zoom <a class="header-anchor" href="#smooth-zoom" aria-label="Permalink to &quot;Smooth zoom&quot;">​</a></h2><p>पास से ज़ूम करने पर आपकी लकीरें धुंधले पिक्सेल के डिब्बों की जगह साफ़ और चिकनी दिखती हैं। मुलायम ब्रश मुलायम ही रहते हैं। सिर्फ़ स्क्रीन पर दिखना बदलता है — आपकी ड्रॉइंग और मूवी बिल्कुल वैसी ही रहती हैं। Android 13 या नया चाहिए। असली पिक्सेल देखने हों (पिक्सेल आर्ट के लिए) तो <strong>Settings → Canvas &amp; gestures → Smooth zoom</strong> बंद करें।</p><p><img src="'+n+'" alt="Smooth zoom बंद और चालू"></p><h2 id="hide-interface" tabindex="-1">Hide interface <a class="header-anchor" href="#hide-interface" aria-label="Permalink to &quot;Hide interface&quot;">​</a></h2><p>ड्रॉइंग ज़्यादा देखने के लिए <strong>hide interface</strong> बटन दबाएँ। कुछ कंट्रोल बचे रहते हैं: मौजूदा टूल, <strong>Show</strong> (सब वापस लाता है), <strong>Copy</strong>, <strong>Paste</strong>, प्ले, फ़्रेम नंबर और <strong>Layers</strong>।</p><p><img src="'+e+'" alt="इंटरफ़ेस छिपा हुआ"></p><h2 id="प्रोजेक्ट-मेन्यू-⋮" tabindex="-1">प्रोजेक्ट मेन्यू (⋮) <a class="header-anchor" href="#प्रोजेक्ट-मेन्यू-⋮" aria-label="Permalink to &quot;प्रोजेक्ट मेन्यू (⋮)&quot;">​</a></h2><p><img src="'+a+'" alt="प्रोजेक्ट मेन्यू"></p><p>ऊपर प्रोजेक्ट का साइज़, रफ़्तार और फ़्रेम की संख्या दिखती है। फिर:</p><ul><li><strong>Add image</strong>, <strong>Add video</strong>, <strong>Audio</strong>, <strong>Objects</strong></li><li><strong>Make sticker</strong>, <strong>Save as object</strong>, <strong>Frames</strong> (सारे फ़्रेम एक ग्रिड में), <strong>Help &amp; tips</strong></li><li><strong>Onion skin</strong> और <strong>Grid</strong> — यहीं चालू या बंद करें; <strong>Edit</strong> से उनकी सेटिंग बदलें</li><li><strong>Project settings</strong> — नाम, रफ़्तार, टाइमिंग, कैनवास के बाहर ड्रॉइंग और बैकग्राउंड</li><li><strong>Make movie</strong></li></ul><h2 id="project-settings" tabindex="-1">Project settings <a class="header-anchor" href="#project-settings" aria-label="Permalink to &quot;Project settings&quot;">​</a></h2><p><img src="'+g+'" alt="प्रोजेक्ट सेटिंग"></p><ul><li><strong>Project name</strong></li><li><strong>Frames per second</strong> — पूरे एनिमेशन की रफ़्तार (1 से 60)</li><li><strong>Timing</strong> — हर ड्रॉइंग 1, 2 या 3 फ़्रेम तक दिखे (<strong>On ones / On twos / On threes</strong>)</li><li><strong>Canvas size</strong> — यहाँ दिखता है, पर प्रोजेक्ट बनने के बाद तय रहता है</li><li><strong>Draw outside the canvas</strong> — कैनवास के चारों ओर ड्रॉ करने की जगह, और <strong>Room size</strong> से वह कितनी हो (<em>तस्वीर, वीडियो और ऑब्जेक्ट</em> देखें)</li><li><strong>Background</strong> — प्रीसेट, कोई रंग या तस्वीर</li><li><strong>Stage background</strong> — ड्रॉ करते समय कैनवास के आसपास का रंग (मूवी में नहीं आता)</li></ul><p>सेव करने के लिए <strong>✓</strong>, बिना सेव किए बंद करने के लिए <strong>✕</strong> पर टैप करें।</p><h2 id="एडिटर-से-निकलना" tabindex="-1">एडिटर से निकलना <a class="header-anchor" href="#एडिटर-से-निकलना" aria-label="Permalink to &quot;एडिटर से निकलना&quot;">​</a></h2><p><strong>✕</strong> या फ़ोन का बैक बटन सेव करके बंद करता है। बैक बटन पहले जो भी खुला हो (मेन्यू, शीट, चुनाव) उसे बंद करता है, इसलिए निकलने के लिए दोबारा दबाएँ।</p>',35)])])}const x=i(c,[["render",p]]);export{k as __pageData,x as default};
